def permute_string(s):
    if len(s) == 0:
        return []
    elif len(s) == 1:
        return [s]
    else:
        permutations = []
        for i in range(len(s)):
            rest = s[:i] + s[i+1:]
            for p in permute_string(rest):
                permutations.append(s[i] + p)
        return permutations

def permute_string(string):
    if len(string) == 1:
        return [string]

    permutations = []
    for i in range(len(string)):
        current_char = string[i]
        remaining_chars = string[:i] + string[i+1:]
        for permutation in permute_string(remaining_chars):
            permutations.append(current_char + permutation)

    return permutations

